import {screenFlow} from './code-index.js';
import {resultCard,referenceResults} from './code-results.js';
import {codeOnlyHTML,readableCode} from './code-tools.js';
import {documentSaved,toggleDocument,visitDocument} from './personal-docs.js';
import {catalogGroups} from './catalog-data.js';
import {catalogBrowser,filterCatalog,materialOptions} from './catalog-view.js';
import {glossary,termPanel,documentGuide,documentTitle} from './plain-language.js';
import {documents,coverage,loadArchive,findDocuments,readDocument,snippet,categories} from './archive-store.js';
import {renderDocument,escape as esc} from './document-renderer.js';
import {eventCatalog,eventFlows} from './event-catalog.js';
let deps={},query='',category='전체',source='전체',limit=12,mode='all',selected='',request=0,current=null,blocks=[],groupId='',topicId='',material='code';
const qs=s=>document.querySelector(s);
const url=u=>{try{const v=new URL(u);return v.protocol==='https:'?esc(v.href):'#'}catch{return '#'}};
const modeFromRoute=()=>location.hash.startsWith('#recipes')?'recipes':location.hash.startsWith('#events')?'events':'all';
export function archivePage(){request++;const nextMode=modeFromRoute();if(nextMode!==mode){query='';category='전체';source='전체';material=nextMode==='recipes'?'complete':'code';limit=12;}mode=nextMode;return `<section class="archive-page"><header class="archive-heading"><div class="archive-kicker">ABAP / REFERENCE</div><h1>${mode==='events'?'이벤트 사전':mode==='recipes'?'전체 코드로 따라 만들기':'작업별 ABAP 자료실'}</h1><p>${mode==='events'?'언제 실행되는지, 무엇을 연결하는지, 전체 예제는 어디 있는지.':mode==='recipes'?'선언부터 화면 연결까지. 프로그램 소스와 화면 Flow Logic을 구분해서 복사하세요.':'기능을 검색하면 실제 코드가 먼저 나옵니다. 결과에서 확인하고, 선택한 코드 전체를 바로 복사하세요.'}</p></header><div class="archive-search"><label class="sr-label" for="archive-search">문서 본문과 코드 검색</label><span aria-hidden="true">⌕</span><input id="archive-search" type="search" placeholder="예: 행 삭제, 더블클릭, 화면 나누기, 엑셀 양식…" value="${esc(query)}" autocomplete="off"><kbd>/</kbd></div><div class="archive-options"><label>읽을 자료 <select id="archive-material">${materialOptions.map(([id,label])=>`<option value="${id}" ${material===id?'selected':''}>${label}</option>`).join('')}</select></label><label>출처 <select id="archive-source"><option>전체</option><option ${source==='Notion'?'selected':''}>Notion</option><option ${source==='GitHub'?'selected':''}>GitHub</option><option ${source==='학습 문서'?'selected':''}>학습 문서</option></select></label><label hidden>분류 <select id="archive-category">${categories.map(c=>`<option ${category===c?'selected':''}>${c}</option>`).join('')}</select></label><span id="archive-status" role="status">본문 색인을 불러오는 중…</span><button data-glossary-open>용어부터 보기</button><button data-archive-coverage>수집 현황</button></div><div id="catalog-browser"></div><div id="event-intro"></div><div class="archive-workspace"><aside class="archive-list" aria-label="검색 결과"><div id="archive-results"></div></aside><article class="archive-reader" id="archive-reader" aria-label="문서 본문"><div class="archive-welcome"><span class="archive-kicker">문서 읽기</span><h2>아래 문서 제목을 눌러 읽으세요.</h2><p>설명과 전체 코드를 함께 볼 수 있어요. 점선 밑줄 용어를 누르면 뜻을 알려드려요.</p><div class="archive-shortcuts">${['ALV','DATA_CHANGED','TOP OF PAGE','엑셀','READ TABLE','INITIALIZATION'].map(q=>`<button data-archive-query="${q}">${q}</button>`).join('')}</div><p class="archive-footnote">자료 수집일 2026.10.18 · 원본 캡처는 본문에서 열람 · 자동 동기화는 하지 않습니다.</p></div></article></div></section>`;}
export async function renderArchive(){try{await loadArchive();if(!qs('#archive-results'))return;const id=decodeURIComponent(location.hash.split('/').slice(1).join('/'));if(!id&&mode!=='events'){groupId='';topicId='';}if(id.startsWith('catalog/')){const parts=id.split('/');groupId=parts[1]||'';topicId=parts[2]||'';}renderList();if(mode==='events')renderEventIntro();if(id&&!id.startsWith('catalog/')){if(mode==='events'&&eventCatalog.some(e=>e.id===id))renderEvent(id);else {const [docId,blockIndex]=id.split('/block/');await openDoc(docId,blockIndex);}}else selected='';}catch(e){if(qs('#archive-results'))qs('#archive-results').innerHTML=`<p class="archive-error">${esc(e.message)} <button data-archive-retry>다시 불러오기</button></p>`;}}
function updateCatalog(){const el=qs('#catalog-browser');if(el)el.innerHTML=mode==='events'?'':catalogBrowser(documents,{groupId,topicId,material,query,mode});const workspace=qs('.archive-workspace');if(workspace)workspace.hidden=mode!=='events'&&!query&&!groupId;}

function mark(text){const q=query.trim().split(/\s+/).find(Boolean);if(!q)return esc(text);const re=new RegExp('('+q.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+')','ig');return String(text).split(re).map((part,i)=>i%2?'<mark>'+esc(part)+'</mark>':esc(part)).join('');}
function renderList(){if(!qs('#archive-results'))return;updateCatalog();if(mode==='events'){const words=query.toLowerCase().split(/\s+/).filter(Boolean),events=eventCatalog.filter(e=>words.every(w=>JSON.stringify(e).toLowerCase().includes(w)));qs('#archive-status').textContent=events.length+'개 이벤트';qs('#archive-results').innerHTML=events.map(e=>`<button class="archive-result ${selected===e.id?'active':''}" data-event-open="${esc(e.id)}"><small>${esc(e.group)}</small><strong>${eventTitle(e.name)}</strong><span class="event-original-name">${mark(e.name)}</span><p>${mark(e.when)}</p></button>`).join('')||'<p class="archive-empty">일치하는 이벤트가 없습니다.</p>';return;}
const allMatches=filterCatalog(findDocuments(query,{category,source,mode}),{groupId,topicId,material:'all'});
const matches=filterCatalog(allMatches,{groupId,topicId,material});
qs('#archive-status').textContent=!query&&!groupId?`${catalogGroups.length}개 분류 · ${mode==='recipes'?matches.length+'개 전체 예제':'코드 있는 자료 '+matches.filter(d=>d.codeInfo.hasCode).length+'개'}`:`${matches.length.toLocaleString()}개 결과 · ${material==='code'?'실제 코드만':material==='reference'?'설명·캡처·목차':materialOptions.find(x=>x[0]===material)?.[1]||''}`;
qs('#archive-results').innerHTML=matches.slice(0,limit).map(d=>resultCard(d,query)).join('')+(matches.length>limit?`<button class="archive-more" data-archive-more>다음 12개 보기 (${limit}/${matches.length})</button>`:'')+(material==='code'?referenceResults(allMatches):'')||'<p class="archive-empty">일치하는 코드가 없습니다. 짧은 키워드나 기능명으로 다시 검색하세요.</p>';
}

function updateSelection(){document.querySelectorAll('[data-archive-open],[data-event-open]').forEach(b=>{b.classList.toggle('active',(b.dataset.archiveOpen||b.dataset.eventOpen)===selected);if(b.classList.contains('active'))b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')});}
async function openDoc(id,blockIndex){const token=++request;selected=id;updateSelection();const reader=qs('#archive-reader');if(!reader)return;qs('.archive-page')?.classList.add('is-reading');qs('.archive-workspace').hidden=false;reader.innerHTML='<p class="archive-loading">문서를 불러오는 중…</p>';try{const d=await readDocument(id);if(token!==request||!qs('#archive-reader'))return;current=d;d.linkTitles=Object.fromEntries(documents.map(x=>[x.id,x.title]));visitDocument(id);blocks=[];blocks.headings=[];const flowSource=screenFlow(d.body);const body=d.format==='database'?databaseBody(d):['code','text'].includes(d.format)?renderDocument('```'+(d.language||'abap')+'\n'+(flowSource||d.body)+'\n```',blocks,d):renderDocument(d.body,blocks,d);const programs=(d.components&&!d.combinedProgram?[]:blocks).map((b,i)=>({b,i})).filter(({b})=>/^\s*(REPORT|PROGRAM)\b/im.test(b.code)&&!/^\s*PROCESS (BEFORE|AFTER)/im.test(b.code)&&!/^\s*INCLUDE\s+[\w/]+\s*\./im.test(b.code)),flows=blocks.map((b,i)=>({b,i})).filter(({b})=>/^\s*PROCESS (BEFORE|AFTER)/im.test(b.code)&&!/^\s*%_/m.test(b.code));reader.innerHTML=`<header class="document-head"><div class="document-reading-nav"><button data-reader-back>← 목록으로 돌아가기</button>${d.track==='RAP'?'<button data-nav="rap">RAP 개발 순서</button>':d.source==='GitHub'?'<button data-nav="github">GitHub 프로젝트</button>':''}<button data-glossary-open>모르는 용어 찾기</button></div><div class="archive-kicker">${esc(d.source)} / ${esc(d.category)}</div><h2 tabindex="-1">${esc(documentTitle(d))}</h2>${documentTitle(d)!==d.title?`<details class="document-original-title"><summary>원문 제목 확인</summary><p>${esc(d.title)}</p></details>`:''}<div class="document-meta"><a href="${url(d.url)}" target="_blank" rel="noopener noreferrer">원본 열기 ↗</a><button data-archive-link>문서 링크 복사</button><button data-document-save aria-pressed="${documentSaved(d.id)}">${documentSaved(d.id)?'★ 저장한 자료':'☆ 자료 저장'}</button><button data-document-copy>문서 전체 복사</button>${blocks.some(b=>/^(abap|sql|cds)?$/i.test(b.lang))?'<button data-document-download>코드만 HTML 저장</button>':''}</div>${flowSource?'<p class="document-notice">화면 배치 정보와 Flow Logic을 분리했습니다. 아래 코드는 SE51의 Flow Logic 탭에 사용하세요. 화면·입력칸·컨테이너는 별도로 준비합니다.</p>':''}${d.path?`<p class="archive-path">${esc(d.path)}</p>`:''}${d.components?'<p class="document-notice">원본 Include별 파일 모음 · 통합본이 있으면 그 블록만 프로그램에 붙이고, Flow Logic은 해당 화면에 붙이세요. <button data-components-download>전체 파일 ZIP 저장</button></p>':''}${blocks.length?'<p class="document-notice">코드는 생략 없이 펼쳐 표시합니다. 원문에 있는 주석·설명도 함께 보존하며, 복사할 때 포함됩니다.</p>':''}${d.recipe&&!d.components?'<p class="document-notice">전체 예제 · 화면·Status·DDIC 객체 준비는 본문의 안내를 확인하세요. SAP 컴파일·실행 미검증.</p>':''}${programs.length||flows.length?`<div class="document-copy-bar">${programs.map(({i},n)=>`<button data-archive-copy="${i}">프로그램 전체 ${programs.length>1?n+1:''} · 주석 포함 복사</button>`).join('')}${flows.map(({i},n)=>`<button data-archive-copy="${i}">화면 Flow Logic ${flows.length>1?n+1:''} 복사</button>`).join('')}</div>`:''}</header>${blocks.headings.length?`<details class="document-toc"><summary>이 문서의 목차 · ${blocks.headings.length}개</summary>${blocks.headings.map(h=>`<a href="#${h.id}" data-doc-section="${h.id}">${esc(h.text)}</a>`).join('')}</details>`:''}<div class="document-body">${!blocks.length?referenceGuide(d):''}${taskGuide(d)}${documentGuide(d)}${body||'<p>원본에 본문이 없는 문서입니다.</p>'}${dependencyLinks(d)}</div><footer class="document-bottom">${d.source==='학습 문서'?'사용자 사례 기반 학습 문서 · 작성일 2026.10.19 · SAP 실행 미검증':esc(d.source)+' 원문을 바탕으로 제공 · 수집일 2026.10.18'}</footer>`;reader.scrollTop=0;if(matchMedia('(max-width:900px)').matches)reader.scrollIntoView({block:'start'});reader.querySelector('h2')?.focus({preventScroll:true});if(blockIndex!==undefined&&/^\d+$/.test(blockIndex))requestAnimationFrame(()=>reader.querySelector('[data-code-block="'+blockIndex+'"]')?.scrollIntoView({block:'start'}));}catch(e){if(token===request&&qs('#archive-reader'))qs('#archive-reader').innerHTML=`<p class="archive-error"><button data-reader-back>← 목록으로 돌아가기</button><br>${esc(e.message)} <a href="https://app.notion.com/p/${esc(id.replace('notion-',''))}" target="_blank" rel="noopener noreferrer">원본 확인</a></p>`;}}
function renderEventIntro(){qs('#event-intro').innerHTML=`<details class="event-flows"><summary>이벤트 실행 흐름 보기</summary>${eventFlows.map(f=>`<div><strong>${esc(f.title)}</strong><p>${f.steps.map(esc).join(' → ')}</p></div>`).join('')}</details>`;qs('#archive-material').closest('label').hidden=true;qs('#archive-source').closest('label').hidden=true;qs('#archive-category').closest('label').hidden=true;}
function renderEvent(id){qs('.archive-page')?.classList.add('is-reading');qs('.archive-workspace').hidden=false;selected=id;updateSelection();const e=eventCatalog.find(e=>e.id===id);if(!e)return;const related=documents.filter(d=>(e.sourceKeywords||[e.name]).some(k=>(d.title+' '+d.text).toUpperCase().includes(k.toUpperCase()))).sort((a,b)=>Number(b.recipe)-Number(a.recipe)||Number(b.source==='Notion')-Number(a.source==='Notion'));qs('#archive-reader').innerHTML=`<header class="document-head"><div class="document-reading-nav"><button data-reader-back>← 이벤트 목록으로</button><button data-glossary-open>모르는 용어 찾기</button></div><div class="archive-kicker">${esc(e.group)}</div><h2>${eventTitle(e.name)}</h2><p class="event-original-name"><code>${esc(e.name)}</code></p><p>${esc(e.when)}</p></header><div class="document-body event-detail">${e.name==='INITIALIZATION'?'<a class="button primary" href="#docs/code/report/initialization">INITIALIZATION에서 쓸 실제 코드 · 역할별 8개 →</a>':''}<h3>연결·등록</h3><p>${esc(e.setup)}</p><h3>주요 값</h3><p>${esc(e.parameters)}</p><h3>처리 순서</h3><p>${esc(e.order)}</p><h3>전체 예제와 원문 ${related.length}개</h3><p>선언·SET HANDLER·실제 처리 FORM은 아래 문서에서 함께 확인하세요.</p>${related.slice(0,30).map(d=>`<button class="event-related" data-doc-link="${esc(d.id)}"><small>${esc(d.source)} · ${d.recipe?'전체 예제':d.category}</small><strong>${esc(d.title)}</strong></button>`).join('')||'<p>연결된 원문이 없습니다.</p>'}</div>`;if(matchMedia('(max-width:900px)').matches)qs('#archive-reader').scrollIntoView({block:'start'});}
function showCoverage(){qs('.archive-page')?.classList.add('is-reading');qs('.archive-workspace').hidden=false;const c=coverage;qs('#archive-reader').innerHTML=`<header class="document-head"><div class="document-reading-nav"><button data-reader-back>← 목록으로 돌아가기</button></div><h2>수집 현황</h2><p>제공된 노션 두 페이지에서 본문 하위 링크를 따라가고, ABAP 지식 사전의 행 목록과 GitHub 전체 파일을 대조했습니다.</p></header><div class="document-body"><div class="coverage-grid">${[['노션 문서',c.notion],['GitHub 원본 파일',c.github],['Notion 캡처',c.notionImages],['프로그램별 파일 묶음',c.programGroups],['노션 전체 코드 예제',c.notionRecipes],['이벤트 사전',eventCatalog.length],['검색 문서 합계',c.documentCount]].map(([label,n])=>`<div><strong>${Number(n).toLocaleString()}</strong><span>${label}</span></div>`).join('')}</div><h3>수집 범위</h3><p>본문과 코드 전체를 검색합니다. 프로그램별 묶음은 같은 원본 파일을 찾아보기 쉽게 연결한 항목으로, 별도 원문 파일 수에 더하지 않습니다.</p><h3>확인할 부분</h3><ul><li>GitHub 원본부터 빈 파일 9개도 포함했습니다. DOCX 1개는 텍스트를 추출했습니다.</li><li>Notion 원본 캡처 ${Number(c.notionImages||0).toLocaleString()}개를 본문에서 표시합니다. 이미지 안의 글자는 검색되지 않습니다. 일부 첨부는 원본 링크로 확인합니다.</li><li>접근할 수 없는 Notion 연결 문서 ${(c.unavailableNotion||[]).length}개는 아래에 남겼습니다.</li><li>원문에 없는 화면·Status·DDIC 객체를 임의로 완성하지 않았습니다. SAP 컴파일·실행은 별도 확인이 필요합니다.</li></ul>${(c.unavailableNotion||[]).map(d=>`<p><a href="${url(d.url)}" target="_blank" rel="noopener noreferrer">읽을 수 없는 연결 문서 · ${esc(d.id.slice(0,8))} ↗</a></p>`).join('')}<h3>분류별 문서</h3>${Object.entries(c.categories||{}).map(([name,n])=>`<p>${esc(name)} <strong>${n}</strong></p>`).join('')}<p class="archive-footnote">2026.10.18 수집본 · 노션·GitHub의 이후 수정 내용은 자동 동기화되지 않습니다.</p></div>`;}
export function bindArchive(d){deps=d;document.addEventListener('input',e=>{if(e.target.id==='archive-search'){query=e.target.value;limit=12;renderList();}});document.addEventListener('change',e=>{if(e.target.hasAttribute?.('data-form-jump')&&e.target.value){const section=e.target.closest('.doc-code'),line=section?.querySelector('[data-code-line="'+e.target.value+'"]');if(line){section.classList.remove('is-folded');const fold=section.querySelector('[data-archive-fold]');if(fold){fold.textContent='접기';fold.setAttribute('aria-expanded','true');}line.scrollIntoView({block:'center',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});section.querySelectorAll?.('.form-jump-target').forEach(el=>el.classList.remove('form-jump-target'));void line.offsetWidth;line.classList.add('form-jump-target');}return;}if(e.target.id==='archive-material'){material=e.target.value;limit=12;renderList();}if(e.target.id==='archive-category'){category=e.target.value;limit=12;renderList()}if(e.target.id==='archive-source'){source=e.target.value;limit=12;renderList()}});document.addEventListener('click',e=>{const b=e.target.closest('button,a');if(!b)return;if(b.hasAttribute('data-reader-back')){deps.navigate(mode==='events'?'events':mode==='recipes'?'recipes':'docs',groupId&&mode!=='events'?'catalog/'+groupId+(topicId?'/'+topicId:''):'');return;}if(b.hasAttribute('data-catalog-home')){groupId='';topicId='';query='';deps.navigate(mode==='recipes'?'recipes':'docs');return;}if(b.dataset.catalogGroup){groupId=b.dataset.catalogGroup;topicId='';query='';deps.navigate(mode==='recipes'?'recipes':'docs','catalog/'+groupId);return;}if(b.dataset.catalogTopic){[groupId,topicId]=b.dataset.catalogTopic.split('/');query='';deps.navigate(mode==='recipes'?'recipes':'docs','catalog/'+groupId+'/'+topicId);return;}if(b.hasAttribute('data-catalog-clear-search')){query='';qs('#archive-search').value='';renderList();return;}if(b.dataset.term){openTerm(b.dataset.term);return;}if(b.hasAttribute('data-term-close')){qs('#term-dialog')?.close();qs('#term-dialog')?.remove();return;}if(b.hasAttribute('data-glossary-open')){openGlossary();return;}if(b.dataset.archiveOpen){deps.navigate(mode==='recipes'?'recipes':'docs',b.dataset.archiveOpen);return;}if(b.dataset.docLink){e.preventDefault();deps.navigate('docs',b.dataset.docLink);return;}if(b.dataset.eventOpen){deps.navigate('events',b.dataset.eventOpen);return;}if(b.dataset.archiveQuery){query=b.dataset.archiveQuery;qs('#archive-search').value=query;limit=12;renderList();return;}if(b.hasAttribute('data-archive-more')){limit+=12;renderList();return;}if(b.hasAttribute('data-archive-coverage')){showCoverage();return;}if(b.hasAttribute('data-archive-retry')){renderArchive();return;}if(b.dataset.docSection){e.preventDefault();qs('#'+b.dataset.docSection)?.scrollIntoView({block:'start'});return;}if(b.hasAttribute('data-archive-fold')){const section=b.closest('.doc-code'),folded=section.classList.toggle('is-folded');b.textContent=folded?'전체 펼치기':'접기';b.setAttribute('aria-expanded',String(!folded));return;}if(b.hasAttribute('data-document-save')&&current){const saved=toggleDocument(current.id);b.textContent=saved?'★ 저장한 자료':'☆ 자료 저장';b.setAttribute('aria-pressed',String(saved));deps.toast(saved?'즐겨찾기에 원문을 저장했습니다.':'저장을 해제했습니다.');return;}if(b.hasAttribute('data-document-copy')&&current){deps.copy('# '+current.title+'\n\n'+current.body,current.title+' · 설명·코드·주석 전체');return;}if(b.dataset.archiveCopy!==undefined){const block=blocks[Number(b.dataset.archiveCopy)];if(block)deps.copy(readableCode(block.code),current.title);return;}if(b.dataset.archiveDownload!==undefined){const block=blocks[Number(b.dataset.archiveDownload)];if(block){if(/^(abap|sql|cds)?$/i.test(block.lang))deps.download(current.id+'-'+b.dataset.archiveDownload+'.html',codeOnlyHTML(current.title,block.code),'text/html;charset=utf-8');else{const extension=({javascript:'js',typescript:'ts',xml:'xml',css:'css',html:'html',json:'json'})[block.lang.toLowerCase()]||'txt';deps.download(current.id+'-'+b.dataset.archiveDownload+'.'+extension,block.code);}}return;}if(b.hasAttribute('data-components-download')&&current?.components){deps.download(current.program+'-sources.zip',deps.zip(current.components.map(c=>({name:c.path,code:c.body}))), 'application/zip');return;}if(b.hasAttribute('data-document-download')&&current){const code=blocks.filter(b=>/^(abap|sql|cds)?$/i.test(b.lang||'')).map(b=>readableCode(b.code)).join('\n\n');if(!code.trim()){deps.toast('코드가 없는 설명 문서입니다. 코드가 포함된 자료를 선택하세요.');return;}deps.download(current.id+'.html',codeOnlyHTML(current.title,code),'text/html;charset=utf-8');return;}if(b.hasAttribute('data-archive-link'))deps.copy(location.href,'문서 링크');});}

function openTerm(id){let dialog=qs('#term-dialog');if(!dialog){dialog=document.createElement('dialog');dialog.id='term-dialog';dialog.className='term-dialog';dialog.setAttribute('aria-label','용어 풀이');document.body.append(dialog);dialog.addEventListener('cancel',()=>dialog.remove());}dialog.innerHTML=termPanel(id);if(!dialog.open)dialog.showModal();}
function openGlossary(){let dialog=qs('#term-dialog');if(!dialog){dialog=document.createElement('dialog');dialog.id='term-dialog';dialog.className='term-dialog';dialog.setAttribute('aria-label','쉬운 용어 사전');document.body.append(dialog);dialog.addEventListener('cancel',()=>dialog.remove());}dialog.innerHTML=`<header><span>쉬운 용어 사전</span><button data-term-close>닫기 ×</button></header><h2>이 말이 무슨 뜻인가요?</h2><p>용어를 누르면 쉬운 뜻과 설정 위치를 확인할 수 있어요.</p><div class="glossary-list">${glossary.map(g=>`<button data-term="${g.id}">${esc(g.term)}</button>`).join('')}</div>`;if(!dialog.open)dialog.showModal();}

function eventTitle(name){const titles={'AT SELECTION-SCREEN ON field':'조회조건 한 필드의 입력값 검사','AT SELECTION-SCREEN ON BLOCK block':'조회조건 한 묶음의 입력값 검사','AT SELECTION-SCREEN ON RADIOBUTTON GROUP group':'라디오 선택 묶음 검사','AT SELECTION-SCREEN':'실행 전 조회조건 검사','FIELD ... MODULE ... ON REQUEST':'사용자가 바꾼 입력칸 처리','FIELD ... MODULE ... ON INPUT':'값이 입력된 필드 처리','PROCESS ON VALUE-REQUEST · POV':'화면 입력칸의 F4 도움말','PROCESS ON HELP-REQUEST · POH':'화면 입력칸의 F1 도움말','BEFORE_USER_COMMAND':'ALV 기본 버튼 실행 전에 처리','AFTER_USER_COMMAND':'ALV 기본 버튼 실행 뒤 처리','FINISHED · CL_GUI_TIMER':'타이머 시간이 끝났을 때','LOAD-OF-PROGRAM':'프로그램을 불러올 때','INITIALIZATION':'조회조건의 처음 기본값 넣기','START-OF-SELECTION':'실행 버튼을 누른 뒤 조회 시작','END-OF-SELECTION':'조회 처리가 끝난 뒤','DOUBLE_CLICK':'행을 더블클릭했을 때','HOTSPOT_CLICK':'링크처럼 표시한 셀을 눌렀을 때','DATA_CHANGED':'입력값이 바뀌었을 때 검사','DATA_CHANGED_FINISHED':'입력 변경이 반영된 뒤 후속 처리','TOOLBAR':'ALV 툴바에 버튼 만들기','USER_COMMAND':'ALV 툴바 버튼을 눌렀을 때','BUTTON_CLICK':'ALV 셀 버튼을 눌렀을 때','ONF4':'ALV 셀에서 F4를 눌렀을 때','TOP_OF_PAGE':'ALV 상단에 요약 표시하기','NODE_DOUBLE_CLICK':'트리 노드를 더블클릭했을 때','FINISHED':'타이머 시간이 끝났을 때'};if(titles[name])return esc(titles[name]);if(name.includes('VALUE-REQUEST'))return '입력칸에서 F4 도움말 열기';if(name.includes('HELP-REQUEST'))return '입력칸에서 F1 도움말 열기';if(name.includes('SELECTION-SCREEN OUTPUT'))return '조회조건 화면을 보여주기 전';if(name.includes('EXIT-COMMAND'))return '종료·뒤로가기 명령 처리';if(name.includes('BEFORE OUTPUT'))return '화면을 보여주기 전 준비';if(name.includes('AFTER INPUT'))return '화면 입력·버튼 처리';return esc(name);}

function taskGuide(d){const t=d.task;if(!t)return '';return `<section class="document-task"><span class="archive-kicker">적용 순서 / 작업 위치</span><h3>${esc(t.title)}</h3><p>${esc(t.intent)}</p><p class="task-location">${esc(t.location)}</p>${t.required?.length?`<dl><dt>준비할 객체</dt><dd>${t.required.map(esc).join('<br>')}</dd></dl>`:''}${t.steps?.length?`<ol>${t.steps.map(x=>`<li>${esc(x)}</li>`).join('')}</ol>`:''}${t.notes?`<p class="task-location">${esc(t.notes)}</p>`:''}</section>`;}
function dependencyLinks(d){const ids=[...(d.relatedObjects||[]),...(d.task?.relatedIds||[]).map(id=>'notion-'+id)];const related=[...new Set(ids)].map(id=>documents.find(x=>x.id===id)).filter(Boolean);return related.length?`<section class="document-dependencies"><h3>연결된 객체·다음 문서</h3>${related.map(x=>`<a href="#docs/${esc(x.id)}" data-doc-link="${esc(x.id)}">${esc(x.title)}</a>`).join('')}</section>`:'';}

function databaseBody(d){return `<section class="document-database"><h3>ABAP 지식 사전 · ${d.databaseItems?.length||0}개 항목</h3><p>노션 데이터베이스의 실제 문서 행입니다. 항목을 누르면 본문과 코드를 읽을 수 있습니다.</p>${(d.databaseItems||[]).map(x=>`<a class="database-row" href="#docs/${esc(x.id)}" data-doc-link="${esc(x.id)}"><span>${esc(x.category)}</span><strong>${esc(x.title)}</strong> →</a>`).join('')}</section>`;}

function referenceGuide(d){
 const info=documents.find(x=>x.id===d.id)?.codeInfo;
 const related=documents.filter(x=>x.id!==d.id&&x.codeInfo?.hasCode&&(d.track==='RAP'?x.track==='RAP':x.category===d.category)).sort((a,b)=>Number(b.recipe)-Number(a.recipe)||Number(b.source==='Notion')-Number(a.source==='Notion')).slice(0,4);
 return `<section class="reference-guide"><strong>${esc(info?.label||'설명 자료')} · 복사할 구현 코드 없음</strong><p>이 원문은 설명·설정·캡처를 확인하는 자료입니다. 실제 코드는 아래 같은 분류의 자료에서 찾아보세요.</p>${related.map(x=>`<button data-doc-link="${esc(x.id)}">${esc(documentTitle(x))} →</button>`).join('')}</section>`;
}
